import java.util.*;

public class Main {
    private static int maxOutsideWord(String text) {
        StringTokenizer st = new StringTokenizer(text, "_");
        int max = 0;
        while (st.hasMoreTokens()) {
            max = Math.max(max, st.nextToken().length());
        }
        return max;
    }

    private static int countInsideWords(String text) {
        StringTokenizer st = new StringTokenizer(text, "_");
        int count = 0;
        while (st.hasMoreTokens()) {
            st.nextToken();
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        boolean openParenthesis = false;
        StringBuilder sb = new StringBuilder();
        int maxOutSide = 0;
        int nbrInside = 0;
        int i = 0;
        while (i < n) {
            char c = s.charAt(i);
            if (c == '(') {
                if (!openParenthesis) {
                    maxOutSide = Math.max(maxOutSide, maxOutsideWord(sb.toString()));
                }
                openParenthesis = true;
                sb.setLength(0);
            } else if (c == ')') {
                openParenthesis = false;
                nbrInside += countInsideWords(sb.toString());
                sb.setLength(0);
            } else {
                sb.append(c);
            }
            i++;
        }
        maxOutSide = Math.max(maxOutSide, maxOutsideWord(sb.toString()));
        System.out.println(maxOutSide + " " + nbrInside);
    }
}
